// Decides what kind of event this is. Nothing is sent or saved here.
const cfg = $('Your settings').first().json;
const ev = $json;
const d = ev.data || {};
const digits = (value) => String(value || '').replace(/\D/g, '');

const base = {
  event_id: ev.id,
  event_type: ev.type,
  message_id: d.id || '',
  number_id: ev.number_id || '',
  content_type: d.content_type || '',
};

// Only private chats: a group message carries the group id in "to".
if (d.to && d.to.group_id) {
  return { json: { ...base, kind: 'ignore', why: 'group message' } };
}

const fromDigits = digits(d.from && d.from.number);
const toDigits = digits(d.to && d.to.number);
const ownerDigits = digits(cfg.owner_phone);
// Numbers this workflow never answers (family, suppliers), comma separated, any format.
const ignoreDigits = String(cfg.ignore_phones || '').split(',').map(digits).filter(Boolean);

// A customer wrote to the number. A quoted answer arrives as message.replied, not message.received.
if ((ev.type === 'message.received' || ev.type === 'message.replied') && d.direction === 'inbound') {
  if (!fromDigits || fromDigits === toDigits) {
    return { json: { ...base, kind: 'ignore', why: 'message from the number itself' } };
  }
  if (fromDigits === ownerDigits) {
    return { json: { ...base, kind: 'ignore', why: 'message from the owner phone' } };
  }
  if (ignoreDigits.includes(fromDigits)) {
    return { json: { ...base, kind: 'ignore', why: 'phone on the ignore list' } };
  }
  return {
    json: {
      ...base,
      kind: 'customer',
      phone: '+' + fromDigits,
      name: (d.from && d.from.name) || '',
      preview: d.preview || '',
    },
  };
}

// A message that leaves the number. Only one typed in the WhatsApp app (origin native) means a
// person took over. Messages sent through the API (origin tn), including this workflow's own, are ignored.
if ((ev.type === 'message.sent' || ev.type === 'message.replied') && d.direction === 'outbound') {
  if (d.origin === 'native' && ignoreDigits.includes(toDigits)) {
    return { json: { ...base, kind: 'ignore', why: 'phone on the ignore list' } };
  }
  if (d.origin === 'native' && toDigits && toDigits !== ownerDigits) {
    return { json: { ...base, kind: 'owner', phone: '+' + toDigits } };
  }
  return { json: { ...base, kind: 'ignore', why: 'own message sent through the API' } };
}

return { json: { ...base, kind: 'ignore', why: 'event not handled' } };

// Applies the rules that must never depend on the AI: duplicates, STOP and START, a person in the
// chat, non-text messages, handoff words and the hourly cap. Nothing is sent or saved here.
const cfg = $('Your settings').first().json;
const ctx = $('Classify the event').item.json;
const msg = $('Read the whole message').item.json;
const row = $json && $json.phone ? $json : null;

const now = $now;
const nowMs = now.toMillis();
const HOUR = 3600 * 1000;

const clean = (value) =>
  String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const squash = (value) => value.replace(/\s+/g, ' ').trim();
const wordList = (value) => String(value || '').split(',').map((w) => squash(clean(w))).filter(Boolean);
const escapeRegex = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const containsWord = (haystack, needle) =>
  new RegExp('(^|[^\\p{L}\\p{N}])' + escapeRegex(needle) + '($|[^\\p{L}\\p{N}])', 'u').test(haystack);

const text = typeof msg.text === 'string' ? msg.text.trim() : '';
const isText = ctx.content_type === 'text';
const normalized = squash(clean(text));
const keyword = normalized.replace(/[^\p{L}\p{N}\s]/gu, '').replace(/\s+/g, ' ').trim();

// What the table remembers about this phone.
const optedOut = Boolean(row && row.opted_out);
const humanUntilMs = row && row.human_until ? new Date(row.human_until).getTime() : 0;
const humanActive = humanUntilMs > nowMs;
const windowStartMs = row && row.ai_window_start ? new Date(row.ai_window_start).getTime() : 0;
const inWindow = windowStartMs > 0 && nowMs - windowStartMs < HOUR;
const answersThisHour = inWindow ? Number(row.ai_answers || 0) : 0;
const recentIds = String((row && row.recent_event_ids) || '').split(',').filter(Boolean);
const recentNext = [...recentIds, ctx.event_id].slice(-20).join(',');

const humanUntilIso = now.plus({ hours: Number(cfg.human_hours) }).toISO();
const untilLabel = now.plus({ hours: Number(cfg.human_hours) }).toFormat('yyyy-LL-dd HH:mm ZZZZ');
const windowIso = inWindow ? row.ai_window_start : now.toISO();

const stateBase = {
  phone: ctx.phone,
  opted_out: optedOut,
  human_until: row && row.human_until ? row.human_until : null,
  last_message_at: now.toISO(),
  ai_answers: answersThisHour,
  ai_window_start: inWindow ? row.ai_window_start : null,
  recent_event_ids: recentNext,
};

const result = {
  ...ctx,
  text,
  route: 'silent',
  reason: '',
  reply_text: '',
  until_label: untilLabel,
  state_after: stateBase,
  state_handoff: { ...stateBase, human_until: humanUntilIso },
};

const pick = (route, reason, replyText, statePatch) => ({
  json: {
    ...result,
    route,
    reason,
    reply_text: replyText || '',
    state_after: { ...stateBase, ...(statePatch || {}) },
  },
});

if (recentIds.includes(ctx.event_id)) return pick('silent', 'event already handled');

// STOP and START are whole-message keywords and always win over everything below.
if (isText && wordList(cfg.optout_words).includes(keyword)) {
  if (optedOut) return pick('silent', 'already opted out');
  return pick('fixed', 'opt-out', cfg.optout_reply, { opted_out: true });
}
if (isText && optedOut && wordList(cfg.optin_words).includes(keyword)) {
  return pick('fixed', 'opt-in', cfg.optin_reply, { opted_out: false });
}
if (optedOut) return pick('silent', 'customer opted out');
if (humanActive) return pick('silent', 'a person is handling this chat');

const capReached = answersThisHour >= Number(cfg.hourly_cap);
const counted = { ai_answers: answersThisHour + 1, ai_window_start: windowIso };

const audioToPerson = cfg.audio_to_person === true || String(cfg.audio_to_person).toLowerCase() === 'true';
if (!isText) {
  if (audioToPerson && ctx.content_type === 'audio') {
    // A voice note is read by a person when the setting says so: no fixed text about "text only", a handover.
    return {
      json: {
        ...result,
        text: text || '(voice note)',
        route: 'handoff',
        reason: 'the customer sent a voice note',
        reply_text: cfg.handoff_reply,
      },
    };
  }
  if (capReached) return pick('silent', 'hourly cap reached, no more automatic replies');
  return pick('fixed', 'non-text message', cfg.nontext_reply, counted);
}
if (!text) {
  return pick('handoff', 'the message text could not be read', cfg.handoff_reply);
}

const hit = wordList(cfg.handoff_words).find((word) => containsWord(normalized, word));
if (hit) return pick('handoff', 'the customer wrote "' + hit + '"', cfg.handoff_reply);

if (capReached) {
  return pick(
    'handoff',
    'more than ' + cfg.hourly_cap + ' automatic replies to this phone in one hour (possible loop)',
    cfg.handoff_reply,
  );
}

return pick('ai', '', '', counted);

