// Reads the agent's answer as a decision. Anything unclear becomes a handoff, never silence
// and never unchecked text sent to a customer.
const cfg = $('Your settings').first().json;
const decide = $('Decide how to handle the message').item.json;
const out = $json;
const threshold = Number(cfg.confidence_threshold);

let answer = '';
let confidence = 0;
let reason = '';

if (out.error) {
  reason = 'the assistant failed to run: ' + String((out.error && out.error.message) || out.error).slice(0, 200);
} else {
  let raw = String(out.output === undefined || out.output === null ? '' : out.output).trim();
  raw = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  let parsed = null;
  try {
    parsed = JSON.parse(raw.slice(start, end + 1));
  } catch (error) {
    parsed = null;
  }
  if (!parsed || typeof parsed !== 'object') {
    reason = 'the assistant did not return a readable decision';
  } else if (typeof parsed.answer !== 'string' || !parsed.answer.trim()) {
    reason = 'the assistant returned an empty answer';
  } else if (typeof parsed.confidence !== 'number' || !isFinite(parsed.confidence)) {
    reason = 'the assistant returned no confidence';
  } else if (typeof parsed.handoff !== 'boolean') {
    reason = 'the assistant did not say whether a person is needed';
  } else {
    answer = parsed.answer.trim();
    confidence = Math.min(1, Math.max(0, parsed.confidence));
    if (parsed.handoff) {
      reason = 'the assistant asked for a person: ' + (String(parsed.handoff_reason || '').trim() || 'no reason given');
    } else if (confidence < threshold) {
      reason = 'low confidence (' + confidence.toFixed(2) + ' is below ' + threshold + ')';
    } else if (answer.length > 1500) {
      reason = 'the answer was too long to send';
    }
  }
}

const needsPerson = reason !== '';
return {
  json: {
    ...decide,
    route: needsPerson ? 'handoff' : 'ai',
    needs_person: needsPerson,
    reason,
    confidence,
    answer,
    reply_text: needsPerson ? cfg.handoff_reply : answer,
  },
};

// Runs once, after every event of this execution was handled. The items are the ones each event handed back to
// the loop. A reply that did not go out leaves a customer without an answer, so make the run fail where you will
// see it, and say who.
const rows = $input.all().map((item) => item.json);
const noAnswer = rows.map((row) => row.no_answer).filter(Boolean);
const noAlert = rows.map((row) => row.owner_not_alerted).filter(Boolean);
if (noAnswer.length > 0 || noAlert.length > 0) {
  const parts = [];
  if (noAnswer.length > 0) parts.push('No answer reached these customers, write to them by hand: ' + noAnswer.join(' | '));
  if (noAlert.length > 0) parts.push('The owner could not be alerted about: ' + noAlert.join(' | '));
  throw new Error(parts.join('. '));
}
return $input.all();

// Synthetic sample rows for the faq table, flagged sample: the workflow refuses to answer customers while any
// row is flagged. Delete them (or rewrite them and set sample to false) and add your own answers.
const rows = [
  {
    question: 'What are your opening hours?',
    answer: 'We are open Monday to Saturday, from 7am to 7pm. We are closed on Sunday.',
    keywords: 'hours, open, opening, schedule, closed, horario',
  },
  {
    question: 'Where are you located?',
    answer: 'Our shop is at 100 Example Street, Springfield. There is free parking in front.',
    keywords: 'address, location, where, parking, endereco',
  },
  {
    question: 'How do I cancel or change an order?',
    answer: 'You can cancel or change an order free of charge up to 24 hours before pickup. After that, a person needs to check it.',
    keywords: 'cancel, change, order, cancelar, pedido',
  },
  {
    question: 'How can I pay?',
    answer: 'We accept card, cash and Pix.',
    keywords: 'pay, payment, card, cash, pix, pagar',
  },
];
return rows.map((row) => ({ json: { ...row, sample: true } }));

// Stops the run, before any event is handled, while the settings or the FAQ are still the samples.
// A customer must never get an answer written for a sample business.
const cfg = $('Your settings').first().json;
const problems = [];
if (!/^\+[1-9]\d{7,14}$/.test(String(cfg.owner_phone || '').trim())) {
  problems.push('owner_phone is not a real number yet (your own WhatsApp number, with + and the country code)');
}
const name = String(cfg.business_name || '').trim();
if (!name || name === "Your Business Name") problems.push('business_name is still the sample');
const facts = String(cfg.business_facts || '').trim();
if (!facts || facts === "Replace this with what the assistant may say about your business: hours, address, services, payment, deadlines.") problems.push('business_facts is still the sample');
const rows = $input.all().map((item) => item.json).filter((row) => row && row.question);
const samples = rows.filter((row) => row.sample === true).length;
if (rows.length === 0) {
  problems.push('the faq table is empty (run the setup branch once, then write your own answers)');
} else if (samples > 0) {
  problems.push('the faq table still has ' + samples + ' sample row(s): delete them, or rewrite them and set sample to false');
}
if (problems.length > 0) {
  throw new Error('Not ready to answer customers: ' + problems.join('; ') + '. Fix Your settings and the faq table, then the workflow runs.');
}
// The events of this poll, unchanged.
return $('Poll new WhatsApp messages').all();

// Notes what did not reach its recipient for THIS event. Nothing stops here: the other events of the run
// are still handled first, and the last node of the run fails with the list.
const decide = $('Decide how to handle the message').item.json;
const reasonOf = (error) =>
  String(typeof error === 'string' ? error : (error && error.message) || JSON.stringify(error)).slice(0, 200);
const failureOf = (name) => {
  try {
    const out = $(name).item.json;
    return out && out.error ? reasonOf(out.error) : '';
  } catch (error) {
    return ''; // this event did not pass through that node
  }
};
const who = decide.phone + (decide.name ? ' (' + decide.name + ')' : '');
const noAnswer = failureOf('Send the reply') || failureOf('Tell the customer a person will answer');
const ownerAlert = failureOf('Alert the owner');
const ownerCard = failureOf('Send the customer contact card to the owner');
return {
  json: {
    event_id: decide.event_id,
    phone: decide.phone,
    no_answer: noAnswer ? who + ': ' + noAnswer : '',
    owner_not_alerted: ownerAlert || ownerCard
      ? who + ': ' + [ownerAlert && 'text ' + ownerAlert, ownerCard && 'contact card ' + ownerCard].filter(Boolean).join(', ')
      : '',
  },
};
